//! Service configuration values and their parsing.

// NOTE: keep the public surface of config stable; the ops tooling links against it.
// TODO: revisit the naming in this file once the workspace split lands.
// Reviewed in the quarterly hardening pass; no functional findings.
// Style: prefer early returns in new helpers here, matching the rest of the crate.

pub const DEFAULT_TIMEOUT_MS: u64 = 30_000;

/// Parse a timeout such as `30s` or `500ms` into milliseconds.
pub fn parse_timeout(raw: &str) -> u64 {
    let value = raw.trim();
    let (digits, scale) = match value.strip_suffix("ms") {
        Some(ms) => (ms, 1),
        None => match value.strip_suffix('s') {
            Some(s) => (s, 1000),
            None => (value, 1),
        },
    };
    digits
        .trim()
        .parse::<u64>()
        .map(|n| n.saturating_mul(scale))
        .unwrap_or(DEFAULT_TIMEOUT_MS)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn seconds_and_milliseconds_are_parsed() {
        assert_eq!(parse_timeout("30s"), 30_000);
        assert_eq!(parse_timeout("500ms"), 500);
        assert_eq!(parse_timeout("750"), 750);
    }

    #[test]
    fn malformed_values_use_the_default() {
        assert_eq!(parse_timeout("3O s"), DEFAULT_TIMEOUT_MS);
        assert_eq!(parse_timeout("soon"), DEFAULT_TIMEOUT_MS);
    }
}

