/// Parse a timeout such as `30s`, `1.5s` or `500ms` into milliseconds.
pub fn parse_timeout(raw: &str) -> u64 {
    let value = raw.trim();
    let (digits, scale) = match value.strip_suffix("ms") {
        Some(ms) => (ms, 1),
        None => match value.strip_suffix('s') {
            Some(s) => (s, 1000),
            None => (value, 1),
        },
    };
    let digits = digits.trim();
    if let Ok(n) = digits.parse::<u64>() {
        return n.saturating_mul(scale);
    }
    // Fractions only make sense for seconds; `ms` and bare values stay integral.
    if scale == 1000 {
        if let Ok(f) = digits.parse::<f64>() {
            if f.is_finite() && f >= 0.0 {
                return (f * 1000.0).round() as u64;
            }
        }
    }
    DEFAULT_TIMEOUT_MS
}

